scripts.linear_congruential:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    for _ in range(inputs['K']):
        s = (inputs['A'] * s + inputs['B']) % inputs['M']
    return float(s)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0
    n = len(values)
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1
    return float(count)

scripts.compute_gcd:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])
    return float(result)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

